import { lazy, Suspense, useEffect, useRef, useState } from "react"
// eslint-disable-next-line
// @ts-ignore — Bun handles `with { type: "text" }` at bundle time
import sampleJsonl from "./__fixtures__/sample.jsonl" with { type: "text" }
import { parseJsonl } from "./parse"
import type { Entry } from "./types"
import { Transcript } from "./transcript/claude/Transcript"

// Dev-only: load the Agentation visual-feedback toolbar dynamically so it
// gets tree-shaken out of production builds. The conditional below is a
// build-time constant after Bun substitutes process.env.NODE_ENV, so the
// import() is unreachable (and therefore omitted) in prod.
const AgentationDev =
  process.env.NODE_ENV !== "production"
    ? lazy(() => import("./AgentationDev"))
    : null

const STORAGE_KEY = "jsonl-fyi:last"
const STORAGE_LIMIT_BYTES = 4_000_000 // ~4 MB; sessionStorage caps around 5 MB

export function App() {
  const [entries, setEntries] = useState<Entry[] | null>(null)
  const [fileName, setFileName] = useState<string | null>(null)
  const [skipped, setSkipped] = useState(0)
  const [dragOver, setDragOver] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  function loadText(text: string, name: string, persist = true) {
    const result = parseJsonl(text)
    setEntries(result.entries)
    setFileName(name)
    setSkipped(result.skipped)
    if (persist) {
      try {
        if (text.length < STORAGE_LIMIT_BYTES) {
          sessionStorage.setItem(STORAGE_KEY, JSON.stringify({ name, text }))
        } else {
          sessionStorage.removeItem(STORAGE_KEY)
        }
      } catch {
        // sessionStorage may throw (quota, disabled). Non-fatal.
      }
    }
  }

  async function loadFile(file: File) {
    const text = await file.text()
    loadText(text, file.name)
  }

  function reset() {
    setEntries(null)
    setFileName(null)
    setSkipped(0)
    if (inputRef.current) inputRef.current.value = ""
    try {
      sessionStorage.removeItem(STORAGE_KEY)
    } catch {
      // ignore
    }
  }

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    if (params.has("demo")) {
      loadText(sampleJsonl, "sample.jsonl", false)
      return
    }
    try {
      const raw = sessionStorage.getItem(STORAGE_KEY)
      if (raw) {
        const { name, text } = JSON.parse(raw) as { name: string; text: string }
        loadText(text, name, false)
      }
    } catch {
      // ignore parse/storage errors; user can re-drop the file
    }
  }, [])

  return (
    <>
      <header className="app-header">
        <div className="app-header-inner">
          <h1>jsonl.fyi</h1>
          {entries && (
            <div className="meta">
              <span className="filename">{fileName}</span>
              <span className="count">{entries.length} entries</span>
              {skipped > 0 && <span className="skipped">{skipped} malformed</span>}
              <button className="reset" onClick={reset}>Clear</button>
            </div>
          )}
        </div>
      </header>
      <div className="app">
      {!entries && (
        <>
          <div
            className={`drop-zone ${dragOver ? "drag-over" : ""}`}
            onDragOver={e => { e.preventDefault(); setDragOver(true) }}
            onDragLeave={() => setDragOver(false)}
            onDrop={e => {
              e.preventDefault()
              setDragOver(false)
              const f = e.dataTransfer.files[0]
              if (f) void loadFile(f)
            }}
            onClick={() => inputRef.current?.click()}
          >
            <div className="drop-zone-text">
              Drop a Claude session <code>.jsonl</code> here
              <div className="drop-zone-sub">or click to choose a file</div>
            </div>
            <input
              ref={inputRef}
              type="file"
              accept=".jsonl,application/jsonl,text/plain"
              data-testid="file-input"
              style={{ display: "none" }}
              onChange={e => {
                const f = e.target.files?.[0]
                if (f) void loadFile(f)
              }}
            />
          </div>
          <div className="demo-row">
            <button
              className="demo-link"
              onClick={() => loadText(sampleJsonl, "sample.jsonl", false)}
            >
              Load sample
            </button>
          </div>
        </>
      )}

      {entries && <Transcript entries={entries} />}
      <footer className="app-footer">
        Your data is processed locally in the browser
      </footer>
      </div>
      {AgentationDev && (
        <Suspense fallback={null}>
          <AgentationDev />
        </Suspense>
      )}
    </>
  )
}

import type { ReactNode } from "react"
import type { ToolResult } from "../../types"
import { isKnownToolUse } from "./toolTypes"
import type {
  ToolUse,
  BashInput,
  ReadInput,
  EditInput,
  MultiEditInput,
  WriteInput,
  GlobInput,
  GrepInput,
  WebFetchInput,
  WebSearchInput,
  AgentInput,
  TodoWriteInput,
  EnterPlanModeInput,
  ExitPlanModeInput,
  NotebookEditInput,
  ToolSearchInput,
  SkillInput,
} from "./toolTypes"
import {
  Terminal,
  File as FileIcon,
  PencilSimple,
  MagnifyingGlass,
  Paperclip,
  GitDiff,
  Circle,
} from "@phosphor-icons/react"
import { EditDiff } from "../EditDiff"
import { ToolCard } from "../ToolCard"
import { shortPath } from "./toolMeta"
import {
  assertExhaustive,
  Header,
  Field,
  Output,
  Extras,
  hasOutput,
  type CardProps,
} from "../shared"

// ---------------------------------------------------------------------------
// Per-tool components — each destructures every input field; `assertExhaustive`
// guarantees no field is silently dropped if the input type grows.
// ---------------------------------------------------------------------------

function Bash({ input, output }: CardProps<BashInput>) {
  const {
    command,
    description,
    timeout,
    run_in_background,
    dangerouslyDisableSandbox,
    ...rest
  } = input
  assertExhaustive(rest)
  const hasContent =
    !!command ||
    !!description ||
    timeout != null ||
    run_in_background != null ||
    dangerouslyDisableSandbox != null ||
    hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={Terminal} color="tool-muted">
          <span className="tool-label-mono">{command || "Done"}</span>
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {command && <pre className="output cmd">{command}</pre>}
        {(description ||
          timeout != null ||
          run_in_background ||
          dangerouslyDisableSandbox) && (
          <dl className="tool-fields">
            {description && <Field name="description" value={description} />}
            {timeout != null && <Field name="timeout" value={`${timeout}ms`} />}
            {run_in_background && <Field name="run_in_background" value="true" />}
            {dangerouslyDisableSandbox && (
              <Field name="dangerouslyDisableSandbox" value="true" />
            )}
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function Read({ input, output }: CardProps<ReadInput>) {
  const { file_path, offset, limit, pages, ...rest } = input
  assertExhaustive(rest)
  const hasContent =
    offset != null ||
    limit != null ||
    !!pages ||
    hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={FileIcon} color="tool-blue">
          Read{file_path ? ` ${shortPath(file_path)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {(offset != null || limit != null || pages) && (
          <dl className="tool-fields">
            {offset != null && <Field name="offset" value={offset} />}
            {limit != null && <Field name="limit" value={limit} />}
            {pages && <Field name="pages" value={pages} />}
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function Edit({ input, output }: CardProps<EditInput>) {
  const { file_path, old_string, new_string, replace_all, ...rest } = input
  assertExhaustive(rest)
  const hasDiff = !!old_string || !!new_string
  const hasContent = hasDiff || replace_all || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={PencilSimple} color="tool-amber">
          Edited{file_path ? ` ${shortPath(file_path)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {hasDiff && (
          <EditDiff
            filePath={file_path}
            oldString={old_string}
            newString={new_string}
          />
        )}
        {replace_all && (
          <dl className="tool-fields">
            <Field name="replace_all" value="true" />
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function MultiEdit({ input, output }: CardProps<MultiEditInput>) {
  const { file_path, edits, ...rest } = input
  assertExhaustive(rest)
  const hasContent = edits.length > 0 || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={PencilSimple} color="tool-amber">
          Edited{file_path ? ` ${shortPath(file_path)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        <div className="multi-edit">
          {edits.map((e, i) => {
            const { old_string, new_string, replace_all, ...editRest } = e
            assertExhaustive(editRest)
            return (
              <div key={i} className="multi-edit-item">
                {replace_all && (
                  <div className="tool-field-inline">
                    <span className="tool-field-key">replace_all</span> true
                  </div>
                )}
                <EditDiff
                  filePath={file_path}
                  oldString={old_string}
                  newString={new_string}
                />
              </div>
            )
          })}
        </div>
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function Write({ input, output }: CardProps<WriteInput>) {
  const { file_path, content, ...rest } = input
  assertExhaustive(rest)
  const hasContent = !!content || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={PencilSimple} color="tool-amber">
          Wrote{file_path ? ` ${shortPath(file_path)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {content && <pre className="output">{content}</pre>}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function Glob({ input, output }: CardProps<GlobInput>) {
  const { pattern, path, ...rest } = input
  assertExhaustive(rest)
  const hasContent = !!path || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={MagnifyingGlass} color="tool-green">
          Searched files{pattern ? ` ${shortPath(pattern)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {path && (
          <dl className="tool-fields">
            <Field name="path" value={path} />
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function Grep({ input, output }: CardProps<GrepInput>) {
  const {
    pattern,
    path,
    glob,
    type,
    output_mode,
    "-i": caseInsensitive,
    "-n": lineNumbers,
    "-A": after,
    "-B": before,
    "-C": context,
    head_limit,
    multiline,
    ...rest
  } = input
  assertExhaustive(rest)
  const opts: Array<[string, ReactNode]> = []
  if (path) opts.push(["path", path])
  if (glob) opts.push(["glob", glob])
  if (type) opts.push(["type", type])
  if (output_mode) opts.push(["output_mode", output_mode])
  if (caseInsensitive) opts.push(["-i", "true"])
  if (lineNumbers) opts.push(["-n", "true"])
  if (after != null) opts.push(["-A", after])
  if (before != null) opts.push(["-B", before])
  if (context != null) opts.push(["-C", context])
  if (head_limit != null) opts.push(["head_limit", head_limit])
  if (multiline) opts.push(["multiline", "true"])
  const hasContent = opts.length > 0 || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={MagnifyingGlass} color="tool-green">
          Searched code{pattern ? ` ${shortPath(pattern)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {opts.length > 0 && (
          <dl className="tool-fields">
            {opts.map(([k, v]) => (
              <Field key={k} name={k} value={v} />
            ))}
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function WebFetch({ input, output }: CardProps<WebFetchInput>) {
  const { url, prompt, ...rest } = input
  assertExhaustive(rest)
  const hasContent = !!prompt || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={Paperclip} color="tool-violet">
          Fetched{url ? ` ${shortPath(url)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {prompt && (
          <dl className="tool-fields">
            <Field name="prompt" value={prompt} />
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function WebSearch({ input, output }: CardProps<WebSearchInput>) {
  const { query, allowed_domains, blocked_domains, ...rest } = input
  assertExhaustive(rest)
  const hasContent =
    (allowed_domains && allowed_domains.length > 0) ||
    (blocked_domains && blocked_domains.length > 0) ||
    hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={MagnifyingGlass} color="tool-green">
          Searched{query ? ` ${shortPath(query)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {((allowed_domains && allowed_domains.length > 0) ||
          (blocked_domains && blocked_domains.length > 0)) && (
          <dl className="tool-fields">
            {allowed_domains && allowed_domains.length > 0 && (
              <Field name="allowed_domains" value={allowed_domains.join(", ")} />
            )}
            {blocked_domains && blocked_domains.length > 0 && (
              <Field name="blocked_domains" value={blocked_domains.join(", ")} />
            )}
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function Agent({
  input,
  output,
  name,
}: CardProps<AgentInput> & { name: "Task" | "Agent" }) {
  const {
    description,
    prompt,
    subagent_type,
    model,
    mode,
    team_name,
    name: agentName,
    isolation,
    run_in_background,
    ...rest
  } = input
  assertExhaustive(rest)
  const opts: Array<[string, ReactNode]> = []
  if (subagent_type) opts.push(["subagent_type", subagent_type])
  if (model) opts.push(["model", model])
  if (mode) opts.push(["mode", mode])
  if (team_name) opts.push(["team_name", team_name])
  if (agentName) opts.push(["name", agentName])
  if (isolation) opts.push(["isolation", isolation])
  if (run_in_background) opts.push(["run_in_background", "true"])
  const hasContent = !!prompt || opts.length > 0 || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={GitDiff} color="tool-violet">
          {name === "Task" ? "Ran task" : "Ran agent"}
          {description ? ` ${shortPath(description)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {prompt && <pre className="output">{prompt}</pre>}
        {opts.length > 0 && (
          <dl className="tool-fields">
            {opts.map(([k, v]) => (
              <Field key={k} name={k} value={v} />
            ))}
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function TodoWrite({ input, output }: CardProps<TodoWriteInput>) {
  const { todos, ...rest } = input
  assertExhaustive(rest)
  return (
    <ToolCard.Root hasContent={todos.length > 0 || hasOutput(output)}>
      <ToolCard.Trigger>
        <Header icon={PencilSimple} color="tool-amber">
          Updated todos
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        <ul className="todo-list">
          {todos.map((t, i) => {
            const { content, status, activeForm, ...todoRest } = t
            assertExhaustive(todoRest)
            return (
              <li key={i} className={`todo todo-${status}`}>
                <span className="todo-status">{status}</span>
                <span>{status === "in_progress" ? activeForm : content}</span>
              </li>
            )
          })}
        </ul>
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function EnterPlanMode({
  input,
  output,
}: CardProps<EnterPlanModeInput>) {
  const rest: Record<string, never> = input
  assertExhaustive(rest)
  return (
    <ToolCard.Root hasContent={hasOutput(output)}>
      <ToolCard.Trigger>
        <Header icon={Circle} color="tool-muted">
          Entered plan mode
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function ExitPlanMode({
  input,
  output,
}: CardProps<ExitPlanModeInput>) {
  const { plan, ...rest } = input
  assertExhaustive(rest)
  const hasContent = !!plan || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={Circle} color="tool-muted">
          Exited plan mode
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {plan && <pre className="output">{plan}</pre>}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function NotebookEdit({
  input,
  output,
}: CardProps<NotebookEditInput>) {
  const { notebook_path, new_source, cell_id, cell_type, edit_mode, ...rest } =
    input
  assertExhaustive(rest)
  const opts: Array<[string, ReactNode]> = []
  if (cell_id) opts.push(["cell_id", cell_id])
  if (cell_type) opts.push(["cell_type", cell_type])
  if (edit_mode) opts.push(["edit_mode", edit_mode])
  const hasContent =
    !!new_source || opts.length > 0 || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={PencilSimple} color="tool-amber">
          Edited notebook{notebook_path ? ` ${shortPath(notebook_path)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {new_source && <pre className="output">{new_source}</pre>}
        {opts.length > 0 && (
          <dl className="tool-fields">
            {opts.map(([k, v]) => (
              <Field key={k} name={k} value={v} />
            ))}
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function ToolSearch({ input, output }: CardProps<ToolSearchInput>) {
  const { query, max_results, ...rest } = input
  assertExhaustive(rest)
  const hasContent = max_results != null || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={MagnifyingGlass} color="tool-green">
          Searched tools{query ? ` ${shortPath(query)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {max_results != null && (
          <dl className="tool-fields">
            <Field name="max_results" value={max_results} />
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

function Skill({ input, output }: CardProps<SkillInput>) {
  const { skill, args, ...rest } = input
  assertExhaustive(rest)
  const hasContent = !!args || !!output.injectedText || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={Paperclip} color="tool-violet">
          Loaded skill{skill ? ` ${shortPath(skill)}` : ""}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {args && (
          <dl className="tool-fields">
            <Field name="args" value={args} />
          </dl>
        )}
        {output.injectedText && (
          <pre className="output">{output.injectedText}</pre>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

// MCP / unknown — we don't have a typed shape, so render raw fields.
function UnknownTool({
  use,
  output,
}: {
  use: { name: string; input: Record<string, unknown> }
  output: ToolResult
}) {
  const keys = Object.keys(use.input)
  const hasContent = keys.length > 0 || hasOutput(output)
  return (
    <ToolCard.Root hasContent={hasContent}>
      <ToolCard.Trigger>
        <Header icon={Terminal} color="tool-muted">
          Ran {use.name}
        </Header>
      </ToolCard.Trigger>
      <ToolCard.Content>
        {keys.length > 0 && (
          <dl className="tool-fields">
            {keys.map(k => {
              const v = use.input[k]
              return (
                <Field
                  key={k}
                  name={k}
                  value={typeof v === "string" ? v : JSON.stringify(v, null, 2)}
                />
              )
            })}
          </dl>
        )}
        <Output output={output} />
        <Extras output={output} />
      </ToolCard.Content>
    </ToolCard.Root>
  )
}

// ---------------------------------------------------------------------------
// Dispatcher component — exhaustive on KnownToolUse (TS errors on missing case).
// ---------------------------------------------------------------------------

export function Tool({
  use,
  output,
}: {
  use: ToolUse
  output: ToolResult
}) {
  if (!isKnownToolUse(use)) {
    return <UnknownTool use={use} output={output} />
  }
  switch (use.name) {
    case "Bash":
      return <Bash input={use.input} output={output} />
    case "Read":
      return <Read input={use.input} output={output} />
    case "Edit":
      return <Edit input={use.input} output={output} />
    case "MultiEdit":
      return <MultiEdit input={use.input} output={output} />
    case "Write":
      return <Write input={use.input} output={output} />
    case "Glob":
      return <Glob input={use.input} output={output} />
    case "Grep":
      return <Grep input={use.input} output={output} />
    case "WebFetch":
      return <WebFetch input={use.input} output={output} />
    case "WebSearch":
      return <WebSearch input={use.input} output={output} />
    case "Task":
    case "Agent":
      return <Agent name={use.name} input={use.input} output={output} />
    case "TodoWrite":
      return <TodoWrite input={use.input} output={output} />
    case "EnterPlanMode":
      return <EnterPlanMode input={use.input} output={output} />
    case "ExitPlanMode":
      return <ExitPlanMode input={use.input} output={output} />
    case "NotebookEdit":
      return <NotebookEdit input={use.input} output={output} />
    case "ToolSearch":
      return <ToolSearch input={use.input} output={output} />
    case "Skill":
      return <Skill input={use.input} output={output} />
  }
}

// Best-guess input shapes for Claude Code's built-in tools, based on the
// author's experience using them (this file is drafted by Claude Code
// itself). A subsequent script (scripts/infer-tool-schemas.ts) verifies
// these against real `.jsonl` sessions and prints any drift.
//
// Optional fields use `?:`. Fields that I suspect exist but I'm unsure
// about are commented `// rare`. Anything tagged `unknown` means I think
// it's defined by the tool but I don't remember the exact shape.

// ---------------------------------------------------------------------------
// File / shell tools
// ---------------------------------------------------------------------------

export type BashInput = {
  command: string
  description?: string
  timeout?: number // ms; default 120_000
  run_in_background?: boolean
  dangerouslyDisableSandbox?: boolean
}

export type ReadInput = {
  file_path: string
  offset?: number // 1-based line number to start at
  limit?: number // max lines to read
  pages?: string // PDF page range like "1-5" or "3"
}

export type EditInput = {
  file_path: string
  old_string: string
  new_string: string
  replace_all?: boolean
}

export type MultiEditInput = {
  file_path: string
  edits: Array<{
    old_string: string
    new_string: string
    replace_all?: boolean
  }>
}

export type WriteInput = {
  file_path: string
  content: string
}

export type GlobInput = {
  pattern: string
  path?: string
}

export type GrepInput = {
  pattern: string
  path?: string
  glob?: string
  type?: string // language/file-type shortcut, e.g. "ts", "py"
  output_mode?: "content" | "files_with_matches" | "count"
  "-i"?: boolean // case-insensitive
  "-n"?: boolean // include line numbers
  "-A"?: number // lines after match
  "-B"?: number // lines before match
  "-C"?: number // lines before+after match
  head_limit?: number
  multiline?: boolean
}

// ---------------------------------------------------------------------------
// Web tools
// ---------------------------------------------------------------------------

export type WebFetchInput = {
  url: string
  prompt: string
}

export type WebSearchInput = {
  query: string
  allowed_domains?: string[]
  blocked_domains?: string[]
}

// ---------------------------------------------------------------------------
// Agent / orchestration
// ---------------------------------------------------------------------------

// "Agent" and "Task" are the same tool across Claude Code versions; older
// transcripts may use either name. Same input shape.
export type AgentInput = {
  description: string
  prompt: string
  subagent_type?: string
  model?: "sonnet" | "haiku" | "opus" | string
  mode?: string // permission mode, e.g. "plan", "acceptEdits"
  team_name?: string
  name?: string
  isolation?: "worktree"
  run_in_background?: boolean
}

// ---------------------------------------------------------------------------
// Todo / planning
// ---------------------------------------------------------------------------

export type TodoWriteInput = {
  todos: Array<{
    content: string
    status: "pending" | "in_progress" | "completed"
    activeForm: string
  }>
}

export type ExitPlanModeInput = {
  plan: string
}

// Best guess: no required input, just signals the mode switch. Verify.
export type EnterPlanModeInput = Record<string, never>

// ---------------------------------------------------------------------------
// Notebooks
// ---------------------------------------------------------------------------

export type NotebookEditInput = {
  notebook_path: string
  new_source: string
  cell_id?: string
  cell_type?: "code" | "markdown"
  edit_mode?: "replace" | "insert" | "delete"
}

// ---------------------------------------------------------------------------
// Tool / skill system
// ---------------------------------------------------------------------------

export type ToolSearchInput = {
  query: string
  max_results?: number
}

export type SkillInput = {
  skill: string
  args?: string
}

// ---------------------------------------------------------------------------
// Discriminated union
// ---------------------------------------------------------------------------

export type KnownToolUse =
  | { name: "Bash"; input: BashInput }
  | { name: "Read"; input: ReadInput }
  | { name: "Edit"; input: EditInput }
  | { name: "MultiEdit"; input: MultiEditInput }
  | { name: "Write"; input: WriteInput }
  | { name: "Glob"; input: GlobInput }
  | { name: "Grep"; input: GrepInput }
  | { name: "WebFetch"; input: WebFetchInput }
  | { name: "WebSearch"; input: WebSearchInput }
  | { name: "Task"; input: AgentInput }
  | { name: "Agent"; input: AgentInput }
  | { name: "TodoWrite"; input: TodoWriteInput }
  | { name: "EnterPlanMode"; input: EnterPlanModeInput }
  | { name: "ExitPlanMode"; input: ExitPlanModeInput }
  | { name: "NotebookEdit"; input: NotebookEditInput }
  | { name: "ToolSearch"; input: ToolSearchInput }
  | { name: "Skill"; input: SkillInput }

// MCP tools follow the convention `mcp__<server>__<tool>` and have
// server-defined inputs we can't statically type. Any unrecognized name
// falls into this bucket.
export type UnknownToolUse = {
  name: string
  input: Record<string, unknown>
}

export type ToolUse = KnownToolUse | UnknownToolUse

const KNOWN_NAMES = new Set<KnownToolUse["name"]>([
  "Bash",
  "Read",
  "Edit",
  "MultiEdit",
  "Write",
  "Glob",
  "Grep",
  "WebFetch",
  "WebSearch",
  "Task",
  "Agent",
  "TodoWrite",
  "EnterPlanMode",
  "ExitPlanMode",
  "NotebookEdit",
  "ToolSearch",
  "Skill",
])

// Narrow an untyped tool_use block (raw from JSONL) into the discriminated
// union. We trust `name` to discriminate `input`; if Claude Code ever ships
// a known tool with a different shape, it'll surface as a runtime error in
// the body component, which is the right place to notice.
export function narrowToolUse(block: {
  name: string
  input: Record<string, unknown>
}): ToolUse {
  if (KNOWN_NAMES.has(block.name as KnownToolUse["name"])) {
    return block as KnownToolUse
  }
  return block as UnknownToolUse
}

export function isKnownToolUse(use: ToolUse): use is KnownToolUse {
  return KNOWN_NAMES.has(use.name as KnownToolUse["name"])
}

