:root {
  --bg: #0f1115;
  --fg: #e6e6e6;
  --muted: #8a8f98;
  --border: #232730;
  --card: #161922;
  --code-bg: #0b0d12;
  --code-border: rgba(255, 255, 255, 0.1);
  --user-bubble: #2a2d35;
}

@media (prefers-color-scheme: light) {
  :root {
    --bg: #ffffff;
    --fg: #1a1a1a;
    --muted: #6a7280;
    --border: #e3e6eb;
    --card: #f7f8fa;
    --code-bg: #f4f5f7;
    --code-border: rgba(0, 0, 0, 0.12);
    --user-bubble: #ececec;
  }
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui,
    sans-serif;
  font-size: 14px;
  line-height: 1.5;
}

.app {
  max-width: 880px;
  margin: 0 auto;
  padding: 0 16px;
}

.app-header h1 {
  font-size: 14px;
  font-weight: 600;
  margin: 0;
}

.drop-zone {
  border: 2px dashed var(--border);
  border-radius: 12px;
  padding: 64px 16px;
  text-align: center;
  color: var(--muted);
  cursor: pointer;
}

.drop-zone:hover {
  border-color: var(--fg);
  background: var(--card);
}

.drop-zone code {
  font-family: ui-monospace, monospace;
  background: var(--code-bg);
  padding: 2px 6px;
  border-radius: 4px;
}

.user-bubble {
  align-self: flex-end;
  max-width: 75%;
  background: var(--user-bubble);
  padding: 10px 14px;
  border-radius: 16px;
  white-space: pre-wrap;
  margin: 8px 0;
}
.assistant-text {
  white-space: pre-wrap;
  padding: 4px 0;
}
.icon-muted {
  color: var(--muted);
  flex-shrink: 0;
  margin-top: 2px;
}
.thinking {
  display: flex;
  align-items: center;
  gap: 8px;
  text-align: left;
  color: var(--muted);
  font-style: italic;
  padding: 4px 6px;
  background: none;
  border: none;
  cursor: pointer;
  font: inherit;
}
.thinking:not(.thinking-expanded) {
  max-width: 50%;
}
.thinking-icon {
  color: var(--muted);
  flex-shrink: 0;
}
.thinking-content {
  flex: 1;
  min-width: 0;
  font-style: italic;
}
.thinking:not(.thinking-expanded) .thinking-content {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.thinking-expanded {
  align-items: flex-start;
}
.thinking-expanded .thinking-content {
  white-space: pre-wrap;
}
.thinking-expanded .thinking-icon {
  margin-top: 2px;
}
.image-block {
  display: inline-block;
  margin: 4px 0;
}
.image-block-user {
  align-self: flex-end;
}
.image-block img {
  max-width: 100%;
  max-height: 320px;
  border: 1px solid var(--border);
  border-radius: 4px;
  display: block;
}

.tool-card {
  display: flex;
  flex-direction: column;
}
.tool-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  border-radius: 4px;
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  color: inherit;
  font: inherit;
}
.tool-row.clickable {
  cursor: pointer;
}
.tool-row.clickable:hover {
  background: var(--card);
}
.tool-row .icon {
  flex-shrink: 0;
}
.tool-row > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tool-row > span.tool-label-mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.92em;
}
.tool-fields {
  display: grid;
  grid-template-columns: max-content 1fr;
  column-gap: 12px;
  row-gap: 2px;
  margin: 0;
  font-size: 12px;
}
.tool-field {
  display: contents;
}
.tool-field dt {
  color: var(--muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}
.tool-field dd {
  margin: 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  white-space: pre-wrap;
  word-break: break-word;
}
.tool-field dd code {
  background: none;
  padding: 0;
}
.tool-field-inline {
  font-size: 12px;
  color: var(--muted);
}
.tool-field-key {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}
.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 13px;
}
.todo {
  display: flex;
  gap: 8px;
  align-items: baseline;
}
.todo-status {
  font-size: 11px;
  color: var(--muted);
  text-transform: uppercase;
  min-width: 88px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}
.todo-completed span:last-child {
  text-decoration: line-through;
  color: var(--muted);
}
.icon.tool-blue {
  color: #7ab7ff;
}
.icon.tool-amber {
  color: #f5b870;
}
.icon.tool-green {
  color: #74d99f;
}
.icon.tool-violet {
  color: #c79bf3;
}
.icon.tool-muted {
  color: var(--muted);
}
.tool-body {
  margin: 4px 0 8px 24px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.cmd,
.output {
  font-size: 12px;
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-radius: 4px;
  padding: 8px 10px;
  margin: 0;
  max-height: 480px;
  overflow: auto;
  white-space: pre-wrap;
  word-break: break-word;
}
.cmd {
  color: var(--muted);
}
.multi-edit {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.edit-diff {
  display: block;
  font-size: 12px;
  border: 1px solid var(--code-border);
  border-radius: 4px;
  overflow: hidden;
  max-height: 480px;
}

.tool-refs {
  color: var(--muted);
}
.tool-refs-label {
  font-weight: 500;
  margin-bottom: 4px;
}
.tool-refs ul {
  margin: 0;
  padding: 0 0 0 20px;
}
.tool-refs li {
  padding: 2px 0;
}

.transcript {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.app-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background: var(--bg);
  border-bottom: 1px solid transparent;
  animation: header-border linear both;
  animation-timeline: scroll();
  animation-range: 0 60px;
}
@keyframes header-border {
  to {
    border-bottom-color: var(--border);
  }
}
.app-header-inner {
  max-width: 880px;
  margin: 0 auto;
  padding: 8px 16px;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
}
.meta {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--muted);
}
.meta .filename {
  color: var(--fg);
  font-family: ui-monospace, monospace;
}
.meta .reset {
  color: var(--muted);
  text-decoration: underline;
  cursor: pointer;
  background: none;
  border: none;
  padding: 0;
  font: inherit;
}
.drop-zone-sub {
  margin-top: 8px;
  color: var(--muted);
}
.demo-row {
  text-align: center;
  margin-top: 12px;
}
.demo-link {
  color: var(--muted);
  text-decoration: underline;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
}
.demo-link:hover {
  color: var(--fg);
}
.drop-zone.drag-over {
  border-color: var(--fg);
  background: var(--card);
}

.app-footer {
  margin-top: 48px;
  padding: 16px 0;
  text-align: center;
  color: var(--muted);
}

