            <span />
          )}
          <button
            className="icon-btn settings-btn"
            aria-label="Settings"
            title="Settings"
          >
            <Gear size={16} />
          </button>
        </div>
      </header>
      <div className="app">
      {!entries && (
        <>
          <div
            className={`drop-zone ${dragOver ? "drag-over" : ""}`}
            onDragOver={e => { e.preventDefault(); setDragOver(true) }}
            onDragLeave={() => setDragOver(false)}
            onDrop={e => {
              e.preventDefault()
              setDragOver(false)
              const f = e.dataTransfer.files[0]
              if (f) void loadFile(f)
            }}
            onClick={() => inputRef.current?.click()}
          >
            <div className="drop-zone-text">
              Drop a Claude session <code>.jsonl</code> here
              <div className="drop-zone-sub">or click to choose a file</div>
            </div>
            <input
              ref={inputRef}
              type="file"
              accept=".jsonl,application/jsonl,text/plain"
              data-testid="file-input"
              style={{ display: "none" }}
              onChange={e => {
                const f = e.target.files?.[0]
                if (f) void loadFile(f)
              }}
            />
          </div>
          <div className="demo-row">
            <button
              className="demo-link"
              onClick={() => loadText(sampleJsonl, "sample.jsonl", false)}
            >
              Load sample
            </button>
          </div>
        </>
      )}

      {entries && <Transcript entries={entries} />}
      <footer className="app-footer">
        Your data is processed locally in the browser
      </footer>
      </div>
      {AgentationDev && (
        <Suspense fallback={null}>
          <AgentationDev />
        </Suspense>
      )}
    </>
  )
}

