:root {
  --bg: #0f1115;
  --fg: #e6e6e6;
  --muted: #8a8f98;
  --border: #232730;
  --card: #161922;
  --code-bg: #0b0d12;
  --code-border: rgba(255, 255, 255, 0.1);
  --user-bubble: #2a2d35;

  --fs-base: 15px;
  --fs-sm: 13px;
}

@media (prefers-color-scheme: light) {
  :root {
    --bg: #ffffff;
    --fg: #1a1a1a;
    --muted: #6a7280;
    --border: #e3e6eb;
    --card: #f7f8fa;
    --code-bg: #f4f5f7;
    --code-border: rgba(0, 0, 0, 0.12);
    --user-bubble: #ececec;
  }
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui,
    sans-serif;
  font-size: var(--fs-base);
  line-height: 1.5;
}

.app {
  max-width: 880px;
  margin: 0 auto;
  padding: 0 16px;
}

.app-header h1 {
  font-size: var(--fs-base);
  font-weight: 600;
  margin: 0;
}

.drop-zone {
  border: 2px dashed var(--border);
  border-radius: 12px;
  padding: 96px 16px;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--muted);
  cursor: pointer;
  margin-top: 32px;
}
.drop-zone-hint {
  margin: 24px 0 0;
  text-align: center;
  font-size: var(--fs-sm);
  color: var(--muted);
}
.drop-zone-hint code {
  font-family: ui-monospace, monospace;
  background: var(--code-bg);
  padding: 2px 6px;
  border-radius: 4px;
}

.drop-zone:hover {
  border-color: var(--fg);
  background: var(--card);
}

.drop-zone code {
  font-family: ui-monospace, monospace;
  background: var(--code-bg);
  padding: 2px 6px;
  border-radius: 4px;
}

.user-bubble {
  align-self: flex-end;
  max-width: 75%;
  background: var(--user-bubble);
  padding: 10px 14px;
  border-radius: 16px;
  white-space: pre-wrap;
  margin: 8px 0;
}
.assistant-text {
  white-space: pre-wrap;
  padding: 4px 0;
}
.icon-muted {
  color: var(--muted);
  flex-shrink: 0;
  margin-top: 2px;
}
.thinking {
  display: flex;
  align-items: center;
  gap: 8px;
  text-align: left;
  color: var(--muted);
  font-style: italic;
  padding: 4px 6px;
  background: none;
  border: none;
  cursor: pointer;
  font: inherit;
}
.thinking:not(.thinking-expanded) {
  max-width: 50%;
}
.thinking-icon {
  color: var(--muted);
  flex-shrink: 0;
}
.thinking-content {
  flex: 1;
  min-width: 0;
  font-style: italic;
}
.thinking:not(.thinking-expanded) .thinking-content {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.thinking-expanded {
  align-items: flex-start;
}
.thinking-expanded .thinking-content {
  white-space: pre-wrap;
}
.thinking-expanded .thinking-icon {
  margin-top: 2px;
}
.image-block {
  display: inline-block;
  margin: 4px 0;
}
.image-block-user {
  align-self: flex-end;
}
.image-block img {
  max-width: 100%;
  max-height: 320px;
  border: 1px solid var(--border);
  border-radius: 4px;
  display: block;
}

.tool-card {
  display: flex;
  flex-direction: column;
}
.tool-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 6px;
  border-radius: 4px;
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  color: inherit;
  font: inherit;
}
.tool-row.clickable {
  cursor: pointer;
}
.tool-row.clickable:hover {
  background: var(--card);
}
.tool-row .icon {
  flex-shrink: 0;
}
.tool-row > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
